package core

// Steam 1.4 multiplayer UDP SO_BROADCAST injection, port of the experimentally
// tested PROBE v2. New code only; no copyrighted game executable is included.
// The patch is allowed only on exact known Steam 1.4 builds.

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
)

const (
	BroadcastHookVA  = 0x004f6b27
	BroadcastOrigSHA = SteamOriginal
	BroadcastMD5SHA  = SteamMD5
)

var BroadcastMarker = []byte("AGTMP2_FIXED_ABI\x00")

func BroadcastPatched(b []byte) bool {
	// Recognize only exact golden output hashes generated by the verified PROBE v2.
	hash := SHA(b)
	if hash != "988ad60b0bb0d95c4c6130b379e478c612fc820cac963a2348a89d601666e1ce" && hash != "4be02e05a3b59fcaf3120b8feffa636f7e9e07dba6c4e8d82976f3aed07a7ae4" {
		return false
	}
	if len(b) < 0x400 || string(b[:2]) != "MZ" {
		return false
	}
	pe := u32(b, 0x3c)
	if pe < 0 || pe+24 > len(b) || string(b[pe:pe+4]) != "PE\x00\x00" {
		return false
	}
	count := u16(b, pe+6)
	opt := pe + 24
	if opt+2 > len(b) {
		return false
	}
	tbl := opt + u16(b, pe+20)
	if count < 2 || tbl+count*40 > len(b) {
		return false
	}
	last := tbl + (count-1)*40
	if string(bytes.TrimRight(b[last:last+8], "\x00")) != ".agm2" {
		return false
	}
	off, size := u32(b, last+20), u32(b, last+16)
	return off >= 0 && size > 0 && off+size <= len(b) && bytes.Contains(b[off:off+size], BroadcastMarker)
}

type broadAssembler struct {
	code   []byte
	labels map[string]int
	links  []struct {
		at     int
		target string
		rva    int
	}
	dllAt, procAt int
}

func (a *broadAssembler) emit(v ...byte) { a.code = append(a.code, v...) }
func (a *broadAssembler) hex(s string)   { a.code = append(a.code, bfromhex(s)...) }
func (a *broadAssembler) dword(v int) {
	b := make([]byte, 4)
	binary.LittleEndian.PutUint32(b, uint32(v))
	a.emit(b...)
}
func (a *broadAssembler) mark(s string) { a.labels[s] = len(a.code) }
func (a *broadAssembler) call(op string, label string, rva int) {
	a.hex(op)
	at := len(a.code)
	a.dword(0)
	a.links = append(a.links, struct {
		at     int
		target string
		rva    int
	}{at, label, rva})
}
func broadcastPayload(rva int) ([]byte, error) {
	a := &broadAssembler{labels: map[string]int{}}
	a.mark("entry")
	a.hex("ff 74 24 0c ff 74 24 0c ff 74 24 0c") // duplicate socket args
	a.call("e8", "", 0x000ee6e8)                 // imported socket thunk
	a.hex("83 f8 ff")
	a.call("0f 84", "end", 0)
	a.hex("60 64 a1 30 00 00 00 8b 78 08 8d 87")
	a.dllAt = len(a.code)
	a.dword(0)
	a.hex("50 ff 97")
	a.dword(0x001f4f40)
	a.hex("85 c0")
	a.call("0f 84", "cleanup", 0)
	a.hex("8d 97")
	a.procAt = len(a.code)
	a.dword(0)
	a.hex("52 50 ff 97")
	a.dword(0x001f4f38)
	a.hex("85 c0")
	a.call("0f 84", "cleanup", 0)
	a.hex("89 c3 8b 74 24 1c 6a 01 89 e1 6a 04 51 6a 20 68 ff ff 00 00 56 ff d3 83 c4 04")
	a.mark("cleanup")
	a.hex("61")
	a.mark("end")
	a.hex("c2 0c 00")
	a.mark("dll")
	a.emit([]byte("wsock32.dll\x00")...)
	a.mark("proc")
	a.emit([]byte("setsockopt\x00")...)
	a.mark("marker")
	a.emit(BroadcastMarker...)
	binary.LittleEndian.PutUint32(a.code[a.dllAt:], uint32(rva+a.labels["dll"]))
	binary.LittleEndian.PutUint32(a.code[a.procAt:], uint32(rva+a.labels["proc"]))
	for _, l := range a.links {
		dest := l.rva
		if l.target != "" {
			dest = rva + a.labels[l.target]
		}
		delta := dest - (rva + l.at + 4)
		binary.LittleEndian.PutUint32(a.code[l.at:], uint32(int32(delta)))
	}
	if len(a.code) > 0x200 || !bytes.Equal(a.code[a.labels["end"]:a.labels["end"]+3], []byte{0xc2, 0x0c, 0x00}) {
		return nil, errors.New("broadcast payload ABI validation failed")
	}
	return a.code, nil
}

func PatchBroadcastV2(in []byte) ([]byte, error) {
	hash := SHA(in)
	if hash != SteamOriginal && hash != SteamMD5 {
		return nil, fmt.Errorf("Broadcast Fix wymaga ORYGINALNEGO Steam 1.4 lub Steam MD5 Fix SHA256. Obecny: %s", hash)
	}
	if len(in) < 0x400 || string(in[:2]) != "MZ" {
		return nil, errors.New("invalid PE file")
	}
	pe := u32(in, 0x3c)
	if pe+24 >= len(in) || string(in[pe:pe+4]) != "PE\x00\x00" {
		return nil, errors.New("invalid PE signature")
	}
	opt := pe + 24
	n := u16(in, pe+6)
	sh := opt + u16(in, pe+20)
	if u16(in, opt) != 0x10b || u32(in, opt+28) != 0x400000 || u32(in, opt+36) != 0x200 || u32(in, opt+32) != 0x1000 || (n != 10 && n != 11) || sh+(n+1)*40 > u32(in, opt+60) {
		return nil, errors.New("unknown PE header layout")
	}
	textFound := false
	textRaw := 0
	maxRVA := 0
	for j := 0; j < n; j++ {
		at := sh + j*40
		name := string(bytes.TrimRight(in[at:at+8], "\x00"))
		vs, va, rs, raw := u32(in, at+8), u32(in, at+12), u32(in, at+16), u32(in, at+20)
		if name == ".agm2" || name == ".agmp" {
			return nil, errors.New("multiplayer probe already installed")
		}
		if name == ".text" {
			if va != 0x1000 {
				return nil, errors.New(".text RVA mismatch")
			}
			textFound = true
			textRaw = raw
		}
		end := va + rs
		if vs > rs {
			end = va + vs
		}
		if end > maxRVA {
			maxRVA = end
		}
	}
	if !textFound {
		return nil, errors.New(".text section missing")
	}
	hookOff := textRaw + (BroadcastHookVA - 0x401000)
	thunkOff := textRaw + (0x004ee6e8 - 0x00401000)
	if hookOff+5 > len(in) || thunkOff+6 > len(in) || !bytes.Equal(in[hookOff:hookOff+5], bfromhex("e8 bc 7b ff ff")) || !bytes.Equal(in[thunkOff:thunkOff+6], bfromhex("ff 25 e0 50 5f 00")) {
		return nil, errors.New("unexpected socket() call or import thunk")
	}
	newRVA := align(maxRVA, 0x1000)
	newRaw := align(len(in), 0x200)
	payload, e := broadcastPayload(newRVA)
	if e != nil {
		return nil, e
	}
	out := make([]byte, newRaw+align(len(payload), 0x200))
	copy(out, in)
	copy(out[newRaw:], payload)
	hdr := sh + n*40
	copy(out[hdr:hdr+8], []byte{'.', 'a', 'g', 'm', '2', 0, 0, 0})
	put32(out, hdr+8, len(payload))
	put32(out, hdr+12, newRVA)
	put32(out, hdr+16, align(len(payload), 0x200))
	put32(out, hdr+20, newRaw)
	put32(out, hdr+24, 0)
	put32(out, hdr+28, 0)
	put32(out, hdr+32, 0)
	put32(out, hdr+36, 0x60000020)
	put16(out, pe+6, n+1)
	put32(out, opt+4, u32(out, opt+4)+align(len(payload), 0x200))
	put32(out, opt+56, align(newRVA+len(payload), 0x1000))
	delta := newRVA - (BroadcastHookVA - 0x400000 + 5)
	out[hookOff] = 0xe8
	binary.LittleEndian.PutUint32(out[hookOff+1:], uint32(int32(delta)))
	checkOff := opt + 64
	put32(out, checkOff, 0)
	put32(out, checkOff, int(checksumPE(out, checkOff)))
	if !BroadcastPatched(out) {
		return nil, errors.New("broadcast output validation failed")
	}
	return out, nil
}
